mapper.select:
SELECT  FROM cms_article a
WHERE a.deleted=0 AND a.status='PUBLISHED' AND a.category_id IN
#{cid}
AND (a.title LIKE #{query.keywordPattern} ESCAPE '!' OR a.content LIKE #{query.keywordPattern} ESCAPE '!')
AND a.location LIKE #{query.locationPattern} ESCAPE '!'
AND a.item_type=#{query.itemType}
AND a.resolution_status=#{query.resolutionStatus}
AND a.event_time >= #{query.from}
AND a.event_time <= #{query.to}
ORDER BY ${query.sortColumn} ${query.sortDirection}, a.id ${query.sortDirection}

SELECT  FROM cms_article a
WHERE a.id=#{id} AND a.deleted=0 AND a.status='PUBLISHED' AND a.category_id IN
#{cid}

SELECT id,title,content,author_id,category_id,status,item_type,event_time,location,contact_info,
       resolution_status,resolved_at,published_at,created_at,updated_at,deleted,version
FROM cms_article WHERE deleted=0
AND status=#{query.status}
AND author_id=#{query.authorId}
ORDER BY created_at DESC,id DESC

mapper.update:
UPDATE cms_article SET status = #{nextStatus}, version = version + 1,
       updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND deleted = 0 AND status = #{expectedStatus}
  AND version = #{expectedVersion}

UPDATE cms_article
SET status = #{targetStatus},
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
    , published_at = #{publishedAt}
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND version = #{version}
  AND deleted = 0
